const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for the three locations
  const queensland = ee.Geometry.Rectangle([138, -29, 153, -10]); // Queensland region
  const lutDesert = ee.Geometry.Point([58.5, 30.8]); // Lut Desert, Iran
  const elAzizia = ee.Geometry.Point([13.03, 32.53]); // El Azizia, Libya

  // 2. Load MODIS LST data for 2003
  const startDate = '2003-01-01';
  const endDate = '2003-12-31';

  // Function to mask based on QC
  function maskLST(image) {
    const qc = image.select('QC_Day');
    const mask = qc.bitwiseAnd(3).lte(1); // Keep good quality (00 or 01)
    return image.select('LST_Day_1km').updateMask(mask).multiply(0.02); // Scale factor
  }

  // Load collection
  let collection = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate(startDate, endDate)
    .map(maskLST);

  const collectionSize = collection.size().getInfo();
  console.log(`Total images in collection: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No MODIS data found for 2003.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate maximum LST for each region
  // Queensland
  const qldCol = collection.filterBounds(queensland);
  const qldSize = qldCol.size().getInfo();
  console.log(`Queensland images: ${qldSize}`);

  if (qldSize === 0) {
    console.log("No data for Queensland.");
    console.log("<answer>C1</answer>");
    return;
  }

  const qldMax = qldCol.max().reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: queensland,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km');

  const qldCount = qldCol.max().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: queensland,
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km');

  const qldMaxVal = qldMax.getInfo();
  const qldCountVal = qldCount.getInfo();

  console.log(`Queensland: Max=${qldMaxVal}K, Pixels=${qldCountVal}`);

  // Lut Desert
  const lutCol = collection.filterBounds(lutDesert);
  const lutSize = lutCol.size().getInfo();
  console.log(`Lut Desert images: ${lutSize}`);

  if (lutSize === 0) {
    console.log("No data for Lut Desert.");
    console.log("<answer>C1</answer>");
    return;
  }

  const lutMax = lutCol.max().reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: lutDesert.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km');

  const lutMaxVal = lutMax.getInfo();
  console.log(`Lut Desert: Max=${lutMaxVal}K`);

  // El Azizia
  const aziziaCol = collection.filterBounds(elAzizia);
  const aziziaSize = aziziaCol.size().getInfo();
  console.log(`El Azizia images: ${aziziaSize}`);

  if (aziziaSize === 0) {
    console.log("No data for El Azizia.");
    console.log("<answer>C1</answer>");
    return;
  }

  const aziziaMax = aziziaCol.max().reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: elAzizia.buffer(5000),
    scale: 3000,
    maxPixels: 1e9
  }).get('LST_Day_1km');

  const aziziaMaxVal = aziziaMax.getInfo();
  console.log(`El Azizia: Max=${aziziaMaxVal}K`);

  // 4. Validation and comparison
  if (qldCountVal === 0) {
    console.log("No valid pixels for Queensland after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (qldMaxVal === null || lutMaxVal === null || aziziaMaxVal === null) {
    console.log("Calculation failed - null result.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (qldMaxVal < 250 || qldMaxVal > 360 || lutMaxVal < 250 || lutMaxVal > 360 || aziziaMaxVal < 250 || aziziaMaxVal > 360) {
    console.log("Invalid temperature range detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final comparison
  console.log(`\nComparison: QLD(${qldMaxVal.toFixed(2)}K) vs Lut(${lutMaxVal.toFixed(2)}K) vs Azizia(${aziziaMaxVal.toFixed(2)}K)`);

  if (qldMaxVal > lutMaxVal && qldMaxVal > aziziaMaxVal) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
